BEGIN;

-- Ficha de Xiomara Fortuna. Sin cambios de campos.
--
-- Categoría nueva Premios Soberano / Música Alternativa: creada en la edición de
-- 2018 (Diario Libre, 30 ene 2018, "una de las nuevas categorías").
-- Premios: 2021 y 2022 (gala del 22 mar 2023, que cubrió los dos años).
-- No registrados: la estatuilla enviada a domicilio en la doble gala de junio de
-- 2021 (no consta a cuál de los dos años, 2019 o 2020, correspondía) y el premio
-- de la gala de 2019 que Nota Clave llama "Álbum del año" (categoría dudosa).

INSERT INTO award_categories (award_id, name)
SELECT a.id, 'Música Alternativa' FROM awards a WHERE a.name = 'Premios Soberano'
   AND NOT EXISTS (SELECT 1 FROM award_categories c WHERE c.award_id = a.id AND c.name = 'Música Alternativa');

INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
SELECT ar.id, cat.award_id, cat.id, 2021, NULL, true, 'Telenord (23 mar 2023: "Música alternativa: Xiomara Fortuna (los dos años)"); lista oficial 2021 reproducida por diasporadominicana (23 mar 2023); gala de 2023'
  FROM artists ar, award_categories cat JOIN awards a ON a.id = cat.award_id
 WHERE ar.slug = 'xiomara-fortuna' AND a.name = 'Premios Soberano' AND cat.name = 'Música Alternativa'
   AND NOT EXISTS (SELECT 1 FROM artist_awards w WHERE w.artist_id = ar.id AND w.category_id = cat.id AND w.year = 2021);
INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
SELECT ar.id, cat.award_id, cat.id, 2022, NULL, true, 'Hoy, Diario Libre, Acento y MasVip (23 mar 2023), lista de ganadores 2022'
  FROM artists ar, award_categories cat JOIN awards a ON a.id = cat.award_id
 WHERE ar.slug = 'xiomara-fortuna' AND a.name = 'Premios Soberano' AND cat.name = 'Música Alternativa'
   AND NOT EXISTS (SELECT 1 FROM artist_awards w WHERE w.artist_id = ar.id AND w.category_id = cat.id AND w.year = 2022);

